package za.ac.univen.clone;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
class PortalParserTest {
 @Test void rejectsOtherStudents(){assertThrows(ApiProblem.class,()->PortalParser.verifyProfile("<table><tr><th>Student Nbr</th><td>20000002</td></tr></table>","20000001"));assertThrows(ApiProblem.class,()->PortalParser.checked("Student Number: 20000002","20000001"));}
 @Test void doesNotExposeHiddenFields(){var doc=org.jsoup.Jsoup.parse("<div>Visible <input type=hidden value=secret><span hidden>hidden</span><script>token</script><input value='Mobile'></div>");String text=PortalParser.visible(doc.body());assertTrue(text.contains("Visible"));assertTrue(text.contains("Mobile"));assertFalse(text.contains("secret"));assertFalse(text.contains("token"));assertFalse(text.contains("hidden"));}
 @Test void changedColumnsFailClosed(){assertThrows(ApiProblem.class,()->PortalParser.read("<table><tr class=rlheader><td>Wrong</td></tr></table>","contacts","20000001"));}
 @Test void contactsKeepVerifiedColumns(){String html="<p>Student Number: 20000001</p><table><tr class=rlheader><th>Communication Type</th><th>Detail</th><th>Internet Service Provider</th></tr><tr class=rldata><td>Cellphone</td><td>0000000000</td><td></td></tr></table>";var result=PortalParser.read(html,"contacts","20000001");assertEquals("ok",result.get("status"));var tables=Data.list(Data.obj(result.get("data")).get("tables"));assertEquals("0000000000",((List<?>)Data.list(tables.getFirst().get("rows")).getFirst().get("cells")).get(1));}
 @Test void emptyRecordsAreNotErrors(){String html="<table><tr class=rlheader><th>Communication Type</th><th>Detail</th><th>Internet Service Provider</th></tr></table>";assertEquals("empty",PortalParser.read(html,"contacts","20000001").get("status"));}
 @Test void parsesMenuWithoutExecutingJavascript(){String html="<script>var i_text = new Array(\"Student Enquiry\",\"Assessment Status\"); var i_url = new Array(\"\",\"w99pkg.mi_validate_option?a=b\"); var i_level = new Array(1,2);</script>";var menu=PortalParser.menu(html);assertEquals("Student Enquiry",menu.get(1).parent());assertEquals("Assessment Status",menu.get(1).label());assertThrows(ApiProblem.class,()->PortalParser.menu(html.replace("\"Assessment Status\"","alert(1)")));}
 @Test void financialNumbers(){assertEquals(1234.56,Data.number("R 1,234.56"));assertEquals(1234.56,Data.number("1.234,56"));}
 @Test void portalTransportRejectsForeignHosts(){assertThrows(ApiProblem.class,()->PortalTransport.allowed("https://evil.example/pls/prodi41/"));assertThrows(ApiProblem.class,()->PortalTransport.allowed("https://univenierp01.univen.ac.za@evil.example/"));assertThrows(ApiProblem.class,()->PortalTransport.allowed("../outside"));assertEquals("univenierp01.univen.ac.za",PortalTransport.allowed("w99pkg.mi_frame_main").getHost());}
 @Test void noInventedStudentProfileData(){String html="<table><tr><th colspan=2>TEST STUDENT</th></tr><tr><th>Student Nbr</th><td>20000001</td></tr></table>";var result=PortalParser.profile(html,"20000001");var student=Data.obj(result.get("student"));assertEquals("20000001",student.get("studentNumber"));assertEquals("",student.get("profileImageUrl"));assertEquals("Not Registered",student.get("registrationStatus"));assertTrue(Data.list(result.get("modules")).isEmpty());}
 @Test void mimeCannotInjectHeaders(){var ticket=Data.map("id","APP-2026-00000000-0000-0000-0000-000000000001","title","Hello\r\nBcc: attacker@example.com");String raw=MailService.mime(ticket,"Help",Data.text(ticket,"id"),List.of(),false);String decoded=new String(Base64.getUrlDecoder().decode(raw),java.nio.charset.StandardCharsets.UTF_8);assertFalse(decoded.contains("\r\nBcc:"));assertTrue(decoded.contains("To: ICTSupport@univen.ac.za"));}
 @Test void senderDisplayNameCannotImpersonateSupport(){assertFalse(MailService.trusted("ICT Support <attacker@example.com>"));assertFalse(MailService.trusted("person@univen.ac.za.evil.example"));assertTrue(MailService.trusted("technician@univen.ac.za"));}
 @Test void appReferenceLinksGmailReplies(){String reference="APP-2026-e7850a5b-cdcd-4089-9cbf-05152f53bda6";assertTrue(MailService.signatureMatches(reference,"Re: PIN RESET FOR MYACCESS","App reference: "+reference+"\nStatus: In Progress"));assertTrue(MailService.signatureMatches(reference,"Reply","App   reference: "+reference));assertFalse(MailService.signatureMatches(reference,"Unrelated request","No app reference here."));}
}
